INSERT INTO ai_insights (id, facility_id, medicine_id, insight_type, title, content, severity, risk_score, metadata, request_hash, is_read, created_at, expires_at) VALUES
(1, 1, 25, 'SHORTAGE_RISK', 'Critical Ceftriaxone Depletion Forecast', 'AIIMS Apex ICU antibiotic consumption has surged 220% over the last 7 days. At the current burn rate of 45 vials/day, existing stock (25 vials) will reach complete exhaustion within 14 hours. Immediate transfer from Max Super Speciality Hospital Noida (16 km, 1200 surplus vials) or NCR Central Warehouse is strongly recommended.', 'CRITICAL', 96.5, '{"confidence": 0.94, "coverage_days": 0.6, "recommended_donor_id": 4}', 'hash_insight_001', FALSE, '2026-09-17 06:30:00', '2026-09-19 00:00:00'),
(2, 6, 4, 'DEMAND_FORECAST', 'Amoxicillin Pediatric Surge Alert', 'Ghaziabad Community Health Center reports a 180% surge in pediatric respiratory admissions following high particulate matter air quality telemetry. Projected 7-day requirement is 750 capsules vs 120 currently in stock. Rebalancing from Sahibabad Logistics Depot recommended.', 'WARNING', 88.0, '{"confidence": 0.91, "projected_deficit": 630}', 'hash_insight_002', FALSE, '2026-09-17 07:00:00', '2026-09-20 00:00:00'),
(3, 7, 4, 'EXPIRY_ALERT', 'Antibiotic Expiry Risk Warning', 'Batch #BN-EXP-040 (140 capsules of Amoxicillin 500mg) at Greater Noida Trauma Clinic expires in 8 days. Average local consumption is only 6 capsules/day, risking loss of 92 units. Recommended action: Dispatch transfer to high-volume emergency center (Safdarjung or AIIMS).', 'WARNING', 75.0, '{"confidence": 0.98, "days_to_expiry": 8, "units_at_risk": 92}', 'hash_insight_003', TRUE, '2026-09-16 09:00:00', '2026-09-24 00:00:00'),
(4, 11, 20, 'LOGISTICS_RECOMMENDATION', 'Regional Fluid Stock Distribution Rebalance', 'NCR Regional Medical Logistics Warehouse currently maintains 15,000 bottles of Normal Saline. Outer ring clinics (Greater Noida, Faridabad) have dipped below 48-hour safety buffer. Proactive scheduled dispatches of 500 units each advised to optimize regional resilience.', 'INFO', 42.0, '{"confidence": 0.89, "network_resilience_score": 88}', 'hash_insight_004', TRUE, '2026-09-15 10:00:00', '2026-09-22 00:00:00');
